SELECT manager_id, manager_name, manager_password, manager_call FROM manager
manager_name LIKE CONCAT('%', #{managerName}, '%')
LIMIT #{offset}, #{pageSize}

SELECT manager_id, manager_name, manager_password, manager_call
FROM manager
WHERE manager_name = #{managerName} AND manager_password = #{managerPassword}

mapper.update:
UPDATE manager
manager_name = #{managerName}, manager_password = #{managerPassword}, manager_call = #{managerCall},
WHERE manager_id = #{managerId}
